-- Read-only MySQL 5.7 validation. Every violations column must equal zero.
SELECT 'email_tables' AS check_name,ABS(5-COUNT(*)) AS violations FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('institution_email_mutex','institution_email_policy','institution_email_assignment','institution_email_reservation','institution_email_event');
SELECT 'email_mutex' AS check_name,ABS(1-COUNT(*)) AS violations FROM institution_email_mutex WHERE id=1;
SELECT 'email_user_namespace' AS check_name,COUNT(*) AS violations FROM user u LEFT JOIN institution_email_reservation r ON r.address=LOWER(u.email) AND r.user_id=u.id WHERE r.address IS NULL;
SELECT 'email_assignment_namespace' AS check_name,COUNT(*) AS violations FROM institution_email_assignment a LEFT JOIN institution_email_reservation r ON r.address=LOWER(a.email) AND r.institution_id=a.institution_id AND r.assignment_id=a.id WHERE r.address IS NULL;
SELECT 'email_namespace_shape' AS check_name,COUNT(*) AS violations FROM institution_email_reservation WHERE BINARY address<>BINARY LOWER(address) OR NOT((user_id IS NOT NULL AND institution_id IS NULL AND assignment_id IS NULL) OR (user_id IS NULL AND institution_id IS NOT NULL AND assignment_id IS NOT NULL));
SELECT 'email_policy_versions' AS check_name,COUNT(*) AS violations FROM (SELECT institution_id,category FROM institution_email_policy GROUP BY institution_id,category HAVING MIN(revision)<>1 OR MAX(revision)<>COUNT(*) OR COUNT(DISTINCT policy_id)<>1) x;
SELECT 'email_recipient_policy' AS check_name,COUNT(*) AS violations FROM institution_email_assignment a LEFT JOIN institution_email_policy p ON p.institution_id=a.institution_id AND p.category=a.category AND p.revision=a.policy_revision WHERE p.policy_id IS NULL OR a.revision<1 OR (a.student_id IS NOT NULL AND a.teacher_id IS NOT NULL) OR (a.student_id IS NULL AND a.teacher_id IS NULL AND a.membership_id IS NULL);
SELECT 'email_audit_actor' AS check_name,COUNT(*) AS violations FROM institution_email_event e LEFT JOIN institution_membership m ON m.institution_id=e.institution_id AND m.id=e.actor_membership_id AND m.user_id=e.actor_user_id WHERE m.id IS NULL OR JSON_TYPE(e.after_json)<>'OBJECT';
SELECT 'email_foreign_keys' AS check_name,ABS(14-COUNT(*)) AS violations FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN ('institution_email_policy','institution_email_assignment','institution_email_reservation','institution_email_event');
SELECT 'email_triggers' AS check_name,ABS(18-COUNT(*)) AS violations FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('email_reservation_insert','email_reservation_update','email_reservation_delete','email_user_insert','email_user_update','email_policy_insert','email_policy_update','email_policy_delete','email_assignment_insert','email_assignment_reserve','email_assignment_update','email_assignment_override_reserve','email_assignment_delete','email_event_insert','email_event_update','email_event_delete','email_student_profile_link','email_teacher_profile_link');
